export const NAMES=['Marcos Aurélio','Anthony','Brunão','Guto','Joao Victor','Broken','Wilson','Rezende','Davi'];
export const HANDS=['Royal Flush','Straight Flush','Quadra','Full House','Flush','Sequência','Trinca','Dois Pares','Um Par','Carta Alta'];
export const RANKS=['A','K','Q','J','10','9','8','7','6','5','4','3','2'];
export const SUITS=['♠','♥','♦','♣'];
export const COLORS=['#dfdfd7','#c73c46','#357ac0','#16966c','#222a33'];
export const uuid=()=>crypto.randomUUID();
export const clone=x=>structuredClone(x);
export function money(n){return new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(n/100);}
export function cents(value){const s=String(value).trim().replace(/^R\$\s*/,'');if(!/^\d+(?:[.,]\d{1,2})?$/.test(s))throw Error('Informe um valor válido, com até 2 casas decimais.');const [a,b='']=s.replace(',','.').split('.');return integer(Number(a)*100+Number(b.padEnd(2,'0')));}
export function integer(n,min=0,max=100000000){if(!Number.isSafeInteger(n)||n<min||n>max)throw Error('Valor fora do limite permitido.');return n;}
export const inputMoney=n=>(n/100).toFixed(2);
export function initialState(){return {schema:1,revision:0,players:NAMES.map((name,i)=>({id:'00000000-0000-4000-8000-'+String(i+1).padStart(12,'0'),name,avatar:'',active:true})),sessions:[],settings:{buyin:500,rebuy:500,chips:[5,10,25,50,100].map((value,i)=>({value,color:COLORS[i]})),reducedMotion:false,achievements:true},audit:[],operations:[],account:{user_id:'00000000-0000-4000-8000-000000009999',username:'Demonstração',role:'owner',approved:true,active:true,must_change_password:false},accounts:[]};}
export const activeEntries=s=>s.entries.filter(e=>!e.voided);
export function invested(s,id){return activeEntries(s).filter(e=>e.playerId===id).reduce((a,e)=>a+e.amount,0);}
export const rebuys=(s,id)=>activeEntries(s).filter(e=>e.kind==='rebuy'&&(!id||e.playerId===id));
export function totals(s){const investedTotal=s.participants.reduce((a,p)=>a+invested(s,p.playerId),0);const received=s.participants.reduce((a,p)=>a+(s.finals[p.playerId]??0),0);const adjustments=s.cashAdjustments.reduce((a,e)=>a+e.amount,0);return {invested:investedTotal,received,adjustments,difference:investedTotal-received-adjustments,missing:s.participants.filter(p=>s.finals[p.playerId]===undefined).length};}
export const results=s=>s.participants.map(p=>({...p,invested:invested(s,p.playerId),final:s.finals[p.playerId]??null,net:s.finals[p.playerId]===undefined?null:s.finals[p.playerId]-invested(s,p.playerId),rebuys:rebuys(s,p.playerId).length})).sort((a,b)=>(b.net??-Infinity)-(a.net??-Infinity));
export function validSessions(state){return state.sessions.filter(s=>!s.deletedAt&&s.status==='finished'&&totals(s).difference===0&&totals(s).missing===0);}
export function localDate(iso){return new Intl.DateTimeFormat('sv-SE',{timeZone:'America/Sao_Paulo',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(iso));}
export function within(s,from='',to=''){const d=localDate(s.startedAt);return (!from||d>=from)&&(!to||d<=to);}
export function statistics(state,sessions=validSessions(state)){
 return state.players.map(p=>{const games=sessions.filter(s=>s.participants.some(x=>x.playerId===p.id));const rows=games.map(s=>results(s).find(x=>x.playerId===p.id));const rounds=games.flatMap(s=>s.rounds.filter(r=>!r.deleted&&r.winners.includes(p.id)));const wins=rounds.filter(r=>r.winners.length===1);return {...p,games:games.length,buyins:games.reduce((a,s)=>a+activeEntries(s).filter(e=>e.playerId===p.id&&e.kind==='buyin').reduce((v,e)=>v+e.amount,0),0),rebuyAmount:games.reduce((a,s)=>a+rebuys(s,p.id).reduce((v,e)=>v+e.amount,0),0),rebuys:rows.reduce((a,r)=>a+r.rebuys,0),maxRebuys:Math.max(0,...rows.map(r=>r.rebuys)),net:rows.reduce((a,r)=>a+r.net,0),best:rows.length?Math.max(...rows.map(r=>r.net)):null,worst:rows.length?Math.min(...rows.map(r=>r.net)):null,positive:rows.filter(r=>r.net>0).length,negative:rows.filter(r=>r.net<0).length,neutral:rows.filter(r=>r.net===0).length,wins:wins.length,ties:rounds.length-wins.length,hands:HANDS.map(h=>wins.filter(r=>r.hand===h).length),rare:rounds.filter(r=>r.hand&&HANDS.indexOf(r.hand)<=2).length,survivor:rows.some(r=>r.net>0&&r.rebuys===0),first:games.length?games.map(s=>s.startedAt).sort()[0]:null};});
}
export function summary(state,sessions=validSessions(state)){const stats=statistics(state,sessions).filter(p=>p.games);const best=(field)=>stats.length?stats.filter(p=>p[field]===Math.max(...stats.map(x=>x[field]))):[];const worst=stats.length?stats.filter(p=>p.net===Math.min(...stats.map(x=>x.net))):[];const rounds=sessions.flatMap(s=>s.rounds.filter(r=>!r.deleted));const counts=HANDS.map(hand=>({hand,n:rounds.filter(r=>r.hand===hand).length}));const max=Math.max(0,...counts.map(c=>c.n));return {games:sessions.length,people:stats.length,total:sessions.reduce((a,s)=>a+totals(s).invested,0),rebuys:sessions.reduce((a,s)=>a+rebuys(s).length,0),rounds:rounds.length,kings:best('net').filter(p=>p.net>0),losses:worst.filter(p=>p.net<0),presence:best('games'),rebuyLeaders:best('rebuys'),bestNight:best('best').filter(p=>p.best>0),commonHands:counts.filter(c=>c.n===max&&max>0),stats};}
function validateChips(chips){if(!Array.isArray(chips)||chips.length!==5||chips.some((c,i)=>c.value!==[5,10,25,50,100][i]||!/^#[0-9a-f]{6}$/i.test(c.color)))throw Error('Configuração de fichas inválida.');}
function text(v,max=120){if(typeof v!=='string'||!v.trim()||v.trim().length>max)throw Error('Preencha o texto solicitado.');return v.trim();}
function participant(s,id){if(!s.participants.some(p=>p.playerId===id))throw Error('Jogador não participa desta sessão.');}
function validateRound(s,r){integer(r.number,1,100000);if(s.rounds.some(x=>!x.deleted&&x.number===r.number&&x.id!==r.id))throw Error('Esse número de rodada já está registrado.');if(!Array.isArray(r.winners)||!r.winners.length||new Set(r.winners).size!==r.winners.length)throw Error('Escolha pelo menos um vencedor.');r.winners.forEach(id=>participant(s,id));if(r.hand&&!HANDS.includes(r.hand))throw Error('Categoria inválida.');if(typeof r.note!=='string'||r.note.length>1000)throw Error('Observação muito longa.');if(!Array.isArray(r.cards)||r.cards.length>52)throw Error('Cartas inválidas.');if(new Set(r.cards.map(c=>c.rank+c.suit)).size!==r.cards.length)throw Error('Uma carta não pode aparecer duas vezes na mesma rodada.');for(const c of r.cards){if(!RANKS.includes(c.rank)||!SUITS.includes(c.suit))throw Error('Carta inválida.');if(c.owner!=='board')participant(s,c.owner);}if(r.cards.filter(c=>c.owner==='board').length>5)throw Error('Máximo de cinco cartas comunitárias.');for(const p of s.participants){const n=r.cards.filter(c=>c.owner===p.playerId).length;if(n>({texas:2,omaha:4,draw:5}[s.variant]))throw Error('Quantidade de cartas individuais incompatível com a modalidade.');}if(s.variant==='draw'&&r.cards.some(c=>c.owner==='board'))throw Error('Pôquer fechado não tem cartas comunitárias.');}
export function applyCommand(original,cmd,actor='Organizador de teste',now=new Date().toISOString()){
 const state=clone(original);const {type,payload:p={},id,sessionId,expectedRevision}=cmd;if(!id)throw Error('Operação sem identificador.');if(state.operations.includes(id))return state;
 if(state.account&&(state.account.role==='member'||!state.account.approved||state.account.must_change_password))throw Error('Ação permitida somente a organizadores.');
 if(['role','access','restoreSession'].includes(type)&&state.account?.role!=='owner')throw Error('Somente o administrador principal.');
 let s=sessionId?state.sessions.find(x=>x.id===sessionId):null;const before=s?clone(s):null;
 if(sessionId&&!s)throw Error('Sessão não encontrada.');
 if(s&&s.deletedAt&&type!=='restoreSession')throw Error('Partida removida.');
 if(s&&expectedRevision!==s.revision&&!(type==='round'&&!s.rounds.some(r=>r.id===p.id)))throw Error('A sessão mudou em outro aparelho. Atualize e confira antes de tentar novamente.');
 if(s&&s.status!=='active'&&!['reopen','deleteSession','restoreSession'].includes(type))throw Error('Sessão bloqueada. Abra uma correção para alterar.');
 if(['role','access'].includes(type)){const target=state.accounts?.find(a=>a.user_id===p.userId);if(!target||target.role==='owner')throw Error('Conta inexistente ou protegida.');if(type==='role'){if(!['member','organizer'].includes(p.role))throw Error('Permissão inválida.');target.role=p.role;if(p.role==='organizer')target.approved=true;}else{if(typeof p.approved!=='boolean')throw Error('Acesso inválido.');target.approved=p.approved;}}
 else if(type==='player'){const name=text(p.name,60);if(p.avatar&&!/^data:image\/(?:png|jpeg|webp);base64,[a-z0-9+/=]+$/i.test(p.avatar))throw Error('Foto inválida.');if((p.avatar||'').length>200000)throw Error('Foto muito grande.');const existing=state.players.find(x=>x.id===p.id);if(existing)Object.assign(existing,{name,avatar:p.avatar||'',active:p.active!==false});else state.players.push({id:p.id||uuid(),name,avatar:p.avatar||'',active:true});}
 else if(type==='settings'){integer(p.buyin,1);integer(p.rebuy,1);validateChips(p.chips);state.settings=clone(p);}
 else if(type==='create'){integer(p.buyin,1);integer(p.rebuy,1);text(p.ancient,60);if(!['quick','full'].includes(p.mode)||!['texas','omaha','draw'].includes(p.variant))throw Error('Modo inválido.');if(!Array.isArray(p.players)||p.players.length<2||new Set(p.players).size!==p.players.length)throw Error('Selecione ao menos dois jogadores diferentes.');p.players.forEach(id=>{if(!state.players.some(x=>x.id===id&&x.active))throw Error('Jogador indisponível.');});if(!Number.isFinite(Date.parse(p.startedAt)))throw Error('Data inválida.');validateChips(p.chips);if(state.sessions.some(x=>x.id===p.id))throw Error('Sessão já existe.');s={id:p.id,name:(p.name||'Pokerzada da noite').slice(0,100),ancient:p.ancient,startedAt:p.startedAt,endedAt:null,status:'active',mode:p.mode,variant:p.variant,buyin:p.buyin,rebuy:p.rebuy,chips:clone(p.chips),participants:p.players.map((playerId,seat)=>({playerId,seat,present:true})),entries:p.players.map(playerId=>({id:uuid(),playerId,kind:'buyin',amount:p.buyin,at:now,actor,voided:false})),finals:{},counts:[],rounds:[],cashAdjustments:[],revision:0,closures:[]};state.sessions.push(s);}
 else if(type==='rebuy'||type==='adjust'){participant(s,p.playerId);integer(p.amount,type==='adjust'?-100000000:1);if(type==='adjust'){text(p.reason,500);if(!p.amount||invested(s,p.playerId)+p.amount<0)throw Error('Ajuste deixaria investimento inválido.');}s.entries.push({id,playerId:p.playerId,kind:type==='adjust'?'adjustment':'rebuy',amount:p.amount,reason:p.reason||'',at:now,actor,voided:false});}
 else if(type==='void'){text(p.reason,500);const e=s.entries.find(x=>x.id===p.entryId&&!x.voided);if(!e||e.kind==='buyin')throw Error('Use um ajuste para corrigir a entrada inicial.');if(invested(s,e.playerId)-e.amount<0)throw Error('O estorno deixaria investimento negativo.');e.voided=true;e.voidReason=p.reason;}
 else if(type==='cash'){integer(p.amount,-100000000);if(!p.amount)throw Error('Informe um ajuste diferente de zero.');s.cashAdjustments.push({id,amount:p.amount,reason:text(p.reason,500),at:now,actor});}
 else if(type==='final'){participant(s,p.playerId);integer(p.amount);s.finals[p.playerId]=p.amount;}
 else if(type==='count'){participant(s,p.playerId);if(!Array.isArray(p.quantities)||p.quantities.length!==5)throw Error('Contagem inválida.');p.quantities.forEach(q=>integer(q,0,1000000));const amount=p.quantities.reduce((a,q,i)=>a+q*s.chips[i].value,0);integer(amount);s.counts.push({id,playerId:p.playerId,quantities:p.quantities,amount,at:now,actor});if(p.useFinal)s.finals[p.playerId]=amount;}
 else if(type==='mode'){if(!['quick','full'].includes(p.mode))throw Error('Modo inválido.');s.mode=p.mode;}
 else if(type==='chips'){validateChips(p.chips);s.chips=clone(p.chips);}
 else if(type==='presence'){participant(s,p.playerId);s.participants.find(x=>x.playerId===p.playerId).present=!!p.present;}
 else if(type==='round'){const i=s.rounds.findIndex(x=>x.id===p.id);const prior=s.rounds[i];const normalized={...clone(p),number:prior?.number??Math.max(0,...s.rounds.map(x=>x.number))+1,note:prior?.note||''};validateRound(s,normalized);const r={...normalized,at:now,actor,deleted:false};if(i<0)s.rounds.push(r);else s.rounds[i]=r;}
 else if(type==='deleteRound'){text(p.reason,500);const r=s.rounds.find(x=>x.id===p.roundId&&!x.deleted);if(!r)throw Error('Rodada não encontrada.');r.deleted=true;r.deleteReason=p.reason;}
 else if(type==='deleteSession'){text(p.reason,500);s.deletedAt=now;s.deletedBy=state.account?.user_id||actor;s.deleteReason=p.reason;}
 else if(type==='restoreSession'){if(!s.deletedAt)throw Error('A partida não está removida.');text(p.reason,500);delete s.deletedAt;delete s.deletedBy;delete s.deleteReason;s.restoredAt=now;s.restoredBy=state.account?.user_id||actor;}
 else if(type==='finalize'){const t=totals(s);if(t.missing||t.difference!==0)throw Error('Preencha todas as apurações e confira a diferença da mesa.');s.status='finished';s.endedAt=s.endedAt||now;if(Date.parse(s.endedAt)<Date.parse(s.startedAt))throw Error('Início da sessão está no futuro.');s.closures.push({at:now,actor,revision:s.revision+1,results:results(s),totals:t});}
 else if(type==='cancel'){text(p.reason,500);s.status='cancelled';s.endedAt=now;s.cancelReason=p.reason;}
 else if(type==='reopen'){if(s.status!=='finished')throw Error('Apenas sessões finalizadas podem ser reabertas.');text(p.reason,500);s.status='active';s.correctionReason=p.reason;}
 else throw Error('Operação desconhecida.');
 if(s)s.revision++;state.revision++;state.operations.push(id);state.audit.push({id,sessionId:s?.id||null,type,actor,at:now,reason:p.reason||'',before,after:s?clone(s):clone(p)});return state;
}
const choose=(arr,n)=>n===0?[[]]:arr.flatMap((v,i)=>choose(arr.slice(i+1),n-1).map(t=>[v,...t]));
export function fiveCardCategory(cards){if(cards.length!==5)throw Error('São necessárias cinco cartas.');const values=cards.map(c=>({A:14,K:13,Q:12,J:11}[c.rank]||Number(c.rank))).sort((a,b)=>b-a);const counts=Object.values(values.reduce((a,v)=>(a[v]=(a[v]||0)+1,a),{})).sort((a,b)=>b-a);const flush=cards.every(c=>c.suit===cards[0].suit);const straight=new Set(values).size===5&&(values[0]-values[4]===4||values.join(',')==='14,5,4,3,2');if(flush&&straight)return values[0]===14&&values[1]===13?0:1;if(counts[0]===4)return 2;if(counts[0]===3&&counts[1]===2)return 3;if(flush)return 4;if(straight)return 5;if(counts[0]===3)return 6;if(counts[0]===2&&counts[1]===2)return 7;if(counts[0]===2)return 8;return 9;}
export function evaluateRecorded(cards,playerId,variant='texas'){const hole=cards.filter(c=>c.owner===playerId),board=cards.filter(c=>c.owner==='board');let combos;if(variant==='draw'){if(hole.length!==5)return null;combos=[hole];}else if(variant==='omaha'){if(hole.length!==4||board.length<3)return null;combos=choose(hole,2).flatMap(h=>choose(board,3).map(b=>[...h,...b]));}else{if(hole.length!==2||board.length<3)return null;combos=choose([...hole,...board],5);}return HANDS[Math.min(...combos.map(fiveCardCategory))];}


export function validateBackup(data){
 const fail=()=>{throw Error('Backup incompatível ou inválido.');};
 if(!data||data.schema!==1||!Array.isArray(data.players)||!Array.isArray(data.sessions)||!Array.isArray(data.audit)||!Array.isArray(data.operations)||!data.settings)fail();
 const idOk=v=>typeof v==='string'&&/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(v);
 const walk=(v,key='',depth=0)=>{if(depth>60)fail();if(v===null)return;if(['id','playerId','sessionId','actorId','entryId','roundId'].includes(key)&&!idOk(v))fail();if(['at','startedAt','endedAt'].includes(key)&&!Number.isFinite(Date.parse(v)))fail();if(v&&typeof v==='object'){for(const [k,x] of Object.entries(v)){if(['__proto__','constructor','prototype'].includes(k))fail();walk(x,k,depth+1);}}};walk(data);
 integer(data.revision);validateChips(data.settings.chips);integer(data.settings.buyin,1);integer(data.settings.rebuy,1);
 if(new Set(data.players.map(p=>p.id)).size!==data.players.length||new Set(data.sessions.map(s=>s.id)).size!==data.sessions.length)fail();
 for(const p of data.players){if(!idOk(p.id)||typeof p.active!=='boolean')fail();text(p.name,60);if(p.avatar&&(!/^data:image\/(?:png|jpeg|webp);base64,[a-z0-9+/=]+$/i.test(p.avatar)||p.avatar.length>200000))fail();}
 for(const s of data.sessions){if(!idOk(s.id)||!['active','finished','cancelled'].includes(s.status)||!['quick','full'].includes(s.mode)||!['texas','omaha','draw'].includes(s.variant))fail();text(s.name,100);text(s.ancient,60);integer(s.revision);integer(s.buyin,1);integer(s.rebuy,1);validateChips(s.chips);
 if(!Array.isArray(s.participants)||s.participants.length<2||!Array.isArray(s.entries)||!Array.isArray(s.rounds)||!Array.isArray(s.counts)||!Array.isArray(s.closures)||!Array.isArray(s.cashAdjustments)||!s.finals||Array.isArray(s.finals))fail();
 if(new Set(s.participants.map(p=>p.playerId)).size!==s.participants.length)fail();
 for(const p of s.participants){if(!data.players.some(x=>x.id===p.playerId))fail();integer(p.seat);if(typeof p.present!=='boolean')fail();if(s.entries.filter(e=>e.playerId===p.playerId&&e.kind==='buyin'&&!e.voided).length!==1)fail();integer(invested(s,p.playerId));}
 for(const e of s.entries){participant(s,e.playerId);if(!['buyin','rebuy','adjustment'].includes(e.kind)||typeof e.voided!=='boolean')fail();integer(e.amount,e.kind==='adjustment'?-100000000:1);}
 for(const [id,amount] of Object.entries(s.finals)){participant(s,id);integer(amount);}
 for(const c of s.counts){participant(s,c.playerId);if(!Array.isArray(c.quantities)||c.quantities.length!==5)fail();c.quantities.forEach(q=>integer(q,0,1000000));if(c.amount!==c.quantities.reduce((a,q,i)=>a+q*s.chips[i].value,0))fail();}
 for(const c of s.cashAdjustments){integer(c.amount,-100000000);text(c.reason,500);}
 for(const r of s.rounds)if(!r.deleted)validateRound(s,r);
 if(s.status==='finished'&&(totals(s).missing||totals(s).difference))fail();
 }
 if(data.operations.some(id=>!idOk(id)))fail();return clone(data);
}

